/* From Uiverse.io by htwarriors108 - Tags: hover effect, hoverme, multicolor, blur, animation, gradient, card, shadow, blur filter, colorful */
.__UIV_SCOPE__ .card {
  position: absolute;
  width: 190px;
  height: 254px;
  border: 4px solid rgba(255, 255, 255, 0.3);
  border-radius: 0.8em;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: 0.5s;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.__UIV_SCOPE__ .card:hover {
  scale: 1.05;
  rotate: 3deg;
}

.__UIV_SCOPE__ .card::after {
  content: '';
  width: 93%;
  height: 95%;
  position: absolute;
  border-radius: 0.7em;
  background-color: rgba(255, 255, 255, 0.1);
  z-index: 0;
}

.__UIV_SCOPE__ .shadow {
  width: 100%;
  height: 100%;
  background: linear-gradient(315deg, #03a9f4, #ff0058);
  z-index: -1;
  filter: blur(25px);
}

.__UIV_SCOPE__ .txt {
  position: absolute;
  font-weight: 800;
  font-size: 1.6em;
  color: #fff;
}

.__UIV_SCOPE__ .card:hover .shadow {
  animation: rotate 3s linear infinite;
}

@keyframes rotate {
  0% {
    rotate: 0deg;
    background: linear-gradient(315deg, #03a9f4, #ff0058);
  }

  50% {
    rotate: 180deg;
    background: linear-gradient(45deg, #ffbc00, #ff0058);
  }

  100% {
    rotate: 360deg;
    background: linear-gradient(315deg, #4dff03, #00d0ff);
  }
}
